    if (i >= n) throw new IniError('unterminated quoted string', lineNo);
    const c = line[i];
    if (c === '"') {
      return { value: out, end: i + 1 };
    }
    if (c === '\\') {
      if (i + 1 >= n) throw new IniError('unterminated quoted string', lineNo);
      const e = line[i + 1];
      switch (e) {
        case '\\':
          out += '\\';
          i += 2;
          break;
        case '"':
          out += '"';
          i += 2;
          break;
        case 'n':
          out += '\n';
          i += 2;
          break;
        case 'r':
          out += '\r';
          i += 2;
          break;
        case 't':
          out += '\t';
          i += 2;
          break;
        case '0':
          out += '\0';
          i += 2;
          break;
        case ';':
          out += ';';
          i += 2;
          break;
        case '#':
          out += '#';
          i += 2;
          break;
        case '=':
          out += '=';
          i += 2;
          break;
        case '[':
          out += '[';
          i += 2;
          break;
        case ']':
          out += ']';
          i += 2;
          break;
        case 'u': {
          const hex = line.slice(i + 2, i + 6);
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) {
            throw new IniError(`invalid unicode escape: \\u${hex}`, lineNo);
          }
          out += String.fromCharCode(parseInt(hex, 16));
          i += 6;
          break;
        }
        default:
          throw new IniError(`unknown escape sequence: \\${e}`, lineNo);
      }
    } else {
      out += c;
      i += 1;
    }
  }
}

function parseHeaderLine(line, lineNo) {
  if (line[line.length - 1] !== ']') {
    throw new IniError('unterminated section header', lineNo);
  }
  const inner = line.slice(1, -1);
  const n = inner.length;
  let i = 0;
  while (i < n && isSpace(inner[i])) i += 1;
  let name;
  if (inner[i] === '"') {
    const res = parseQuotedToken(inner, i, lineNo);
    name = res.value;
    let k = res.end;
    while (k < n && isSpace(inner[k])) k += 1;
    if (k < n) throw new IniError('unexpected text after quoted section name', lineNo);
  } else {
    name = inner.trim();
  }
  if (name === '') throw new IniError('empty section name', lineNo);
  return name;
}

function parseEntryLine(line, lineNo) {
  const n = line.length;
  let i = 0;
  while (i < n && isSpace(line[i])) i += 1;
  let key;
  if (line[i] === '"') {
    const res = parseQuotedToken(line, i, lineNo);
    key = res.value;
    let k = res.end;
    while (k < n && isSpace(line[k])) k += 1;
    if (k >= n) throw new IniError("missing '=' in entry", lineNo);
    if (line[k] !== '=') throw new IniError('unexpected text after quoted key', lineNo);
    i = k + 1;
  } else {
    const eqIdx = line.indexOf('=', i);
    if (eqIdx === -1) throw new IniError("missing '=' in entry", lineNo);
    key = line.slice(i, eqIdx).trim();
    i = eqIdx + 1;
  }
  if (key === '') throw new IniError('empty key', lineNo);

  let j = i;
  while (j < n && isSpace(line[j])) j += 1;
  let value;
  if (line[j] === '"') {
    const res = parseQuotedToken(line, j, lineNo);
    value = res.value;
    let k = res.end;
    while (k < n && isSpace(line[k])) k += 1;
    if (k < n) throw new IniError('unexpected text after quoted value', lineNo);
  } else {
    value = line.slice(i).trim();
  }
  return { key, value };
}

