  function setEntry(obj, key, value, lineNo) {
    const tracker = getTracker(obj);
    if (!tracker.has(key)) {
      tracker.set(key, true);
      defineOwn(obj, key, value);
      return;
    }
    switch (duplicates) {
      case 'last':
        defineOwn(obj, key, value);
        break;
      case 'first':
        break;
      case 'array': {
        const existing = obj[key];
        if (Array.isArray(existing)) {
          existing.push(value);
        } else {
          defineOwn(obj, key, [existing, value]);
