  let current = global;
  const lines = splitLines(text);
  for (const { content, number } of lines) {
    const line = content.trim();
    if (line === '') continue;
    const c0 = line[0];
    if (c0 === ';' || c0 === '#') continue;
    if (c0 === '[') {
      const name = parseHeaderLine(line, number);
      if (sectionMap.has(name)) {
        current = sectionMap.get(name);
      } else {
        current = {};
        sectionMap.set(name, current);
        defineOwn(sections, name, current);
      }
      continue;
    }
    const { key, value } = parseEntryLine(line, number);
    setEntry(current, key, value, number);
  }
  return { global, sections };
}

function quoteToken(s) {
  let out = '"';
  for (const ch of s) {
    switch (ch) {
      case '\\':
        out += '\\\\';
        break;
      case '"':
        out += '\\"';
        break;
      case '\n':
        out += '\\n';
        break;
      case '\r':
        out += '\\r';
        break;
      case '\t':
        out += '\\t';
        break;
      case '\0':
        out += '\\0';
        break;
      default:
        out += ch;
    }
  }
  return out + '"';
}

